    const rows = pubList().filter(l => l.city === cid && (!st.zona || l.zone === st.zona) && (!st.tema || l.theme === st.tema) && (!st.idioma || l.langs.includes(st.idioma)) && (!st.modelo || l.model === st.modelo) && (!st.turno || !TURNO[st.turno] || l.times.some(TURNO[st.turno]))).sort((a, b) => (b.featured - a.featured) || (b.reviews - a.reviews));
