        SC().agencies.push(ag); funnel('agency'); if (f.get('k') === 'pase') funnel('trial'); Store.save(); Notify.push('vitrina.agencia_registrada', 'Email', 'ops@kipucontrol.com', 'Nueva agencia en la vitrina: ' + n);
