    b.querySelectorAll('[data-ver]').forEach(x => x.onclick = () => { const d = DB.siteDomains.find(z => z.id === x.dataset.ver); d.status = 'verificado'; d.ssl = 'emitido'; d.sslUntil = addDays(T(), 90); d.verifiedAt = T(); Store.save(); Audit.log('Dominio', d.host, 'verificar', 'pendiente_dns', 'verificado'); UI.toast('DNS verificado y SSL emitido para ' + d.host + '.'); App.render(); });
